+// ensure sets UUIDs of the scan target hosts/containers to servers and scanResults.
+// A new UUID is generated with generateFunc only if the host/container doesn't have
+// a valid UUID yet. needsOverwrite is true if any UUID has been newly generated,
+// meaning that the caller has to persist the (possibly) modified servers to config.toml.
+func ensure(servers map[string]c.ServerInfo, path string, scanResults models.ScanResults, generateFunc func() (string, error)) (needsOverwrite bool, err error) {
+	// Sort Host->Container
+	sort.Slice(scanResults, func(i, j int) bool {
+		if scanResults[i].ServerName == scanResults[j].ServerName {
+			return scanResults[i].Container.ContainerID < scanResults[j].Container.ContainerID
+		}
+		return scanResults[i].ServerName < scanResults[j].ServerName
+	})
+
+	re := regexp.MustCompile(reUUID)
+	for i, r := range scanResults {
+		server := servers[r.ServerName]
+		if server.UUIDs == nil {
+			server.UUIDs = map[string]string{}
+		}
+
+		name := ""
+		if r.IsContainer() {
+			name = fmt.Sprintf("%s@%s", r.Container.Name, r.ServerName)
+			// Scanning with the -containers-only flag at scan time, the UUID of Container Host
+			// may not be generated, so check it. Otherwise create a UUID of the Container Host
+			// and set it.
+			if id, ok := server.UUIDs[r.ServerName]; !ok || !re.MatchString(id) {
+				serverUUID, err := generateFunc()
+				if err != nil {
+					return needsOverwrite, xerrors.Errorf("Failed to generate UUID: %w", err)
+				}
+				server.UUIDs[r.ServerName] = serverUUID
+				needsOverwrite = true
+			}
+		} else {
+			name = r.ServerName
+		}
+
+		if id, ok := server.UUIDs[name]; ok && re.MatchString(id) {
+			if r.IsContainer() {
+				scanResults[i].Container.UUID = id
+				scanResults[i].ServerUUID = server.UUIDs[r.ServerName]
+			} else {
+				scanResults[i].ServerUUID = id
+			}
+			servers[r.ServerName] = server
+			// no need to generate a new UUID because it's already assigned and valid
+			continue
+		}
+
+		// Generate a new UUID and set to config and scan result
+		serverUUID, err := generateFunc()
+		if err != nil {
+			return needsOverwrite, err
+		}
+		server.UUIDs[name] = serverUUID
+		servers[r.ServerName] = server
+		needsOverwrite = true
+
+		if r.IsContainer() {
+			scanResults[i].Container.UUID = serverUUID
+			scanResults[i].ServerUUID = server.UUIDs[r.ServerName]
+		} else {
+			scanResults[i].ServerUUID = serverUUID
+		}
+	}
+
+	return needsOverwrite, nil
+}
