 }

+// MakeTableWithTruncatedColumn creates a new table with the given column
+// names, populated with the given rows. The truncatedColumn column will be
+// dynamically resized to fit the width of the terminal (or a default width
+// of 80 if the terminal size can not be determined), while the other
+// columns will be sized to fit their content, up to a maximum width
+// calculated from the terminal size. If truncatedColumn does not match any
+// of the given column names, no column will be truncated.
+func MakeTableWithTruncatedColumn(columnOrder []string, rows [][]string, truncatedColumn string) Table {
+	width, _, err := term.GetSize(int(os.Stdin.Fd()))
+	if err != nil || width <= 0 {
+		width = 80
+	}
+	truncatedColMinSize := 16
+	maxColWidth := width
+	if len(columnOrder) > 1 {
+		maxColWidth = (width - truncatedColMinSize) / (len(columnOrder) - 1)
+	}
+	t := MakeTable([]string{})
+	totalLen := 0
+	columns := []Column{}
+
+	for colIndex, colName := range columnOrder {
+		column := Column{
+			Title:         colName,
+			MaxCellLength: len(colName),
+		}
+		if colName == truncatedColumn { // truncated column is handled separately below
+			columns = append(columns, column)
+			continue
+		}
+		for _, row := range rows {
+			if colIndex >= len(row) {
+				continue
+			}
+			cellLen := row[colIndex]
+			if len(cellLen) > column.MaxCellLength {
+				column.MaxCellLength = len(cellLen)
+			}
+		}
+		if column.MaxCellLength > maxColWidth {
+			column.MaxCellLength = maxColWidth
+			totalLen += column.MaxCellLength + 4 // "...<space>"
+		} else {
+			totalLen += column.MaxCellLength + 1 // +1 for column separator
+		}
+		columns = append(columns, column)
+	}
+
+	for _, column := range columns {
+		if column.Title == truncatedColumn {
+			column.MaxCellLength = width - totalLen - len("... ")
+		}
+		t.AddColumn(column)
+	}
+
+	for _, row := range rows {
+		t.AddRow(row)
+	}
+	return t
+}
+
 // AddColumn adds a column to the table's structure.
 func (t *Table) AddColumn(c Column) {
 	c.width = len(c.Title)
