 // This function supports regex expressions in the Name and Namespace fields,
 // but not for the Kind field.
 // The wildcard (*) expansion is also supported.
+//
+// In addition to the exact "Kind" matches (or wildcard "Kind" matches), this
+// function has two special behaviors involving the "namespace" kind:
+//   - A rule for "kind: namespace" grants access to every resource contained
+//     in that namespace, regardless of its kind, as long as the verb is
+//     allowed by the rule.
+//   - A rule that grants access to a namespaced resource (e.g. pods) also
+//     grants read-only access ("get", "list" and "watch") to the namespace
+//     that contains it, even if there isn't an explicit "kind: namespace"
+//     rule. Write operations on the namespace itself (e.g. "create",
+//     "update", "delete") still require an explicit "kind: namespace" rule.
 func KubeResourceMatchesRegex(input types.KubernetesResource, resources []types.KubernetesResource) (bool, error) {
 	if len(input.Verbs) != 1 {
 		return false, trace.BadParameter("only one verb is supported, input: %v", input.Verbs)
 	}
 	verb := input.Verbs[0]
 	for _, resource := range resources {
-		if input.Kind != resource.Kind && resource.Kind != types.Wildcard {
+		if !kubeResourceKindsCouldMatch(input, resource) {
 			continue
 		}
 		// If the resource has a wildcard verb, it matches all verbs.
@@ -148,7 +159,27 @@ func KubeResourceMatchesRegex(input types.KubernetesResource, resources []types.
 		// it doesn't match.
 		// When the resource has a wildcard verb, we only allow one verb in the
 		// resource input.
-		if len(resource.Verbs) == 0 || resource.Verbs[0] != types.Wildcard && !slices.Contains(resource.Verbs, verb) {
+		if !kubeResourceMatchesVerb(resource.Verbs, verb) {
+			continue
+		}
+
+		switch {
+		// A rule for "kind: namespace" grants access to every resource
+		// within that namespace.
+		case resource.Kind == types.KindKubeNamespace && input.Kind != types.KindKubeNamespace:
+			if ok, err := MatchString(input.Namespace, resource.Name); err != nil || ok {
+				return ok, trace.Wrap(err)
+			}
+			continue
+		// Access to a namespaced resource implies read-only access to the
