+// kubeResourceKindsCouldMatch returns true if the input and resource kinds
+// are compatible, i.e. the resource entry could potentially grant access to
+// the input resource. It's a stricter, kind-only version of the checks
+// performed later by KubeResourceMatchesRegex.
+func kubeResourceKindsCouldMatch(input, resource types.KubernetesResource) bool {
+	switch {
+	case input.Kind == resource.Kind || resource.Kind == types.Wildcard:
+		return true
+	// A "kind: namespace" rule grants access to every other kind of resource
+	// contained within that namespace.
+	case resource.Kind == types.KindKubeNamespace && input.Kind != types.KindKubeNamespace:
+		return true
+	// Access to any namespaced resource implies read-only access to the
+	// namespace itself.
+	case input.Kind == types.KindKubeNamespace && resource.Kind != types.KindKubeNamespace:
+		return true
+	default:
+		return false
+	}
