diff --git a/internal/release/check.go b/internal/release/check.go
new file mode 100644
index 00000000..c00f24cf
--- /dev/null
+++ b/internal/release/check.go
@@ -0,0 +1,97 @@
+package release
+
+import (
+	"context"
+	"fmt"
+	"strings"
+
+	"github.com/blang/semver/v4"
+	"github.com/google/go-github/v32/github"
+)
+
+// Info contains information about the current and latest available
+// version of Flipt, as well as whether an update is available.
+type Info struct {
+	CurrentVersion   string `json:"currentVersion,omitempty"`
+	LatestVersion    string `json:"latestVersion,omitempty"`
+	LatestVersionURL string `json:"latestVersionURL,omitempty"`
+	UpdateAvailable  bool   `json:"updateAvailable"`
+}
+
+// releaseChecker is an interface used to retrieve the latest release
+// of Flipt from an upstream source (e.g. GitHub).
+type releaseChecker interface {
+	getLatestRelease(ctx context.Context) (*github.RepositoryRelease, error)
+}
+
+// githubReleaseChecker implements releaseChecker using the GitHub API.
+type githubReleaseChecker struct{}
+
+func (g *githubReleaseChecker) getLatestRelease(ctx context.Context) (*github.RepositoryRelease, error) {
+	client := github.NewClient(nil)
+	release, _, err := client.Repositories.GetLatestRelease(ctx, "flipt-io", "flipt")
+	if err != nil {
+		return nil, fmt.Errorf("checking for latest version: %w", err)
+	}
+
+	return release, nil
+}
+
+// Check returns information about the current version of Flipt, the latest
+// available release, and whether an update is available.
+func Check(ctx context.Context, version string) (Info, error) {
+	return check(ctx, &githubReleaseChecker{}, version)
+}
+
+func check(ctx context.Context, rc releaseChecker, version string) (Info, error) {
+	cv, err := semver.ParseTolerant(version)
+	if err != nil {
+		return Info{}, fmt.Errorf("parsing current version: %w", err)
+	}
+
+	info := Info{
+		CurrentVersion: cv.String(),
+	}
+
+	release, err := rc.getLatestRelease(ctx)
+	if err != nil {
+		return Info{}, err
+	}
+
+	lv, err := semver.ParseTolerant(release.GetTagName())
+	if err != nil {
+		return Info{}, fmt.Errorf("parsing latest version: %w", err)
+	}
+
+	info.LatestVersion = lv.String()
+
+	if cv.Compare(lv) < 0 {
+		info.UpdateAvailable = true
+		info.LatestVersionURL = release.GetHTMLURL()
+	}
+
+	return info, nil
+}
+
+// preReleaseIdentifiers are substrings that, when present in a version
+// string, indicate that the version is not a proper release (e.g. it is a
+// development build, snapshot, or release-candidate).
+var preReleaseIdentifiers = []string{"dev", "snapshot", "rc"}
+
+// Is returns true if the provided version string represents a proper
+// (non pre-release) version of Flipt.
+func Is(version string) bool {
+	if version == "" {
+		return false
+	}
+
+	version = strings.ToLower(version)
+
+	for _, identifier := range preReleaseIdentifiers {
+		if strings.Contains(version, identifier) {
+			return false
+		}
+	}
+
+	return true
+}

